fileBaselines.content:
:root {
  --bg: #f5f7fb;
  --surface: #ffffff;
  --surface-strong: #ffffff;
  --text: #1f2937;
  --text-muted: #6b7280;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --success: #16a34a;
  --danger: #dc2626;
  --border: #e5e7eb;
  --shadow: 0 24px 80px rgba(15, 23, 42, 0.08);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background 0.35s ease, color 0.35s ease;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea {
  font-family: inherit;
}

.navbar {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand a {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.nav-menu {
  display: flex;
  gap: 24px;
  align-items: center;
}

.nav-menu a {
  color: var(--text-muted);
  position: relative;
  transition: color 0.2s ease;
}

.nav-menu a:hover,
.nav-menu a.active {
  color: var(--text);
}

.nav-menu a.active::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 3px;
  background: var(--primary);
  border-radius: 999px;
}

.nav-toggle,
.theme-toggle {
  display: none;
  border: none;
  background: transparent;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--text);
}

.main,
footer,
section {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
}

.hero-section,
.stock-hero,
.portfolio-hero,
.contact-hero,
.page-intro {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 36px;
  align-items: center;
  padding: 40px 0 20px;
}

.hero-copy h1,
.page-intro h1,
.stock-hero h1,
.contact-hero h1 {
  font-size: clamp(2.5rem, 3.4vw, 4rem);
  line-height: 1.05;
  margin-bottom: 20px;
}

.eyebrow {
  display: inline-block;
  margin-bottom: 16px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.78rem;
}

.hero-copy p,
.stock-description,
.page-intro p,
.contact-hero p {
  max-width: 720px;
  color: var(--text-muted);
  line-height: 1.75;
}

.hero-actions,
.cta-group,
.watchlist-controls,
.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 24px;
}

.btn {
  border: none;
  border-radius: 999px;
  padding: 14px 24px;
  cursor: pointer;
  font-weight: 600;
  transition: transform 0.2s ease, background 0.2s ease;
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-secondary {
  background: rgba(37, 99, 235, 0.08);
  color: var(--text);
}

.btn:hover {
  transform: translateY(-1px);
}

.market-card,
.testimonial-card,
.feature-card,
.index-card,
.market-panel,
.stock-summary-card,
.detail-card,
.mini-card,
.holdings-table,
.contact-card,
.watchlist-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 28px;
  box-shadow: var(--shadow);
  padding: 28px;
  transition: transform 0.2s ease, background 0.35s ease, border-color 0.35s ease;
}

.market-card:hover,
.testimonial-card:hover,
.feature-card:hover,
.index-card:hover,
.market-panel:hover,
.stock-summary-card:hover,
.detail-card:hover,
.mini-card:hover,
.contact-card:hover,
.watchlist-card:hover {
  transform: translateY(-4px);
}

.market-card__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  font-weight: 600;
}

.market-card__body p {
  color: var(--text-muted);
  line-height: 1.7;
}

.info-grid,
.feature-grid,
.testimonial-grid,
.index-grid,
.trending-grid,
.portfolio-cards,
.holdings-table,
.watchlist-grid {
  display: grid;
  gap: 20px;
}

.info-grid {
  grid-template-columns: repeat(3, minmax(220px, 1fr));
}

.feature-grid {
  grid-template-columns: repeat(4, minmax(210px, 1fr));
}

.testimonial-grid {
  grid-template-columns: repeat(3, minmax(240px, 1fr));
}

.index-grid {
  grid-template-columns: repeat(3, minmax(220px, 1fr));
}

.trending-grid {
  grid-template-columns: repeat(3, minmax(240px, 1fr));
}

.portfolio-cards {
  grid-template-columns: repeat(3, minmax(180px, 1fr));
}

.watchlist-grid {
  grid-template-columns: repeat(3, minmax(240px, 1fr));
}

.feature-card h3,
.testimonial-card h4,
.market-panel h3,
.detail-card h4,
.mini-card h4 {
  margin-bottom: 14px;
}

.testimonial-card p {
  color: var(--text-muted);
  margin-bottom: 22px;
  line-height: 1.75;
}

.testimonial-card span,
.market-summary div h3 {
  color: var(--text-muted);
}

.section-heading {
  margin-bottom: 26px;
}

.section-heading h2 {
  font-size: clamp(1.9rem, 2.3vw, 2.6rem);
  line-height: 1.1;
}

.market-summary {
  margin-top: 24px;
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.market-summary div {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 22px;
  padding: 22px;
}

.market-summary h3,
.stock-summary-card h3,
.holdings-section h2,
.trending-section h2,
.stock-hero h1,
.contact-hero h1 {
  margin-bottom: 12px;
}

.status {
  font-weight: 700;
}

.up {
  color: var(--success);
}

.down {
  color: var(--danger);
}

.stock-summary-card ul {
  list-style: none;
  display: grid;
  gap: 12px;
}

.stock-summary-card li {
  display: flex;
  justify-content: space-between;
  color: var(--text-muted);
}

.stock-detail-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(220px, 1fr));
  gap: 20px;
  margin: 32px 0;
}

.detail-card p,
.mini-card p {
  font-size: 1.1rem;
  margin-top: 10px;
}

.holdings-table {
  border-radius: 28px;
  overflow: hidden;
}

.table-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1.5fr 1fr;
  gap: 10px;
  padding: 18px 20px;
  align-items: center;
}

.table-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  font-weight: 700;
}

.table-row:not(.table-header) {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.stock-hero p,
.portfolio-value,
.stock-description,
.watchlist-section p,
.contact-card p,
.contact-form label,
.form-status {
  color: var(--text-muted);
}

.portfolio-value {
  font-size: 2.6rem;
  font-weight: 700;
  margin: 20px 0 0;
}

.watchlist-controls {
  justify-content: space-between;
  gap: 16px;
}

.watchlist-controls input,
.search-bar input,
.contact-form input,
.contact-form textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 16px 18px;
  background: var(--surface);
  color: var(--text);
}

.search-bar input {
  width: 100%;
}

.contact-form {
  display: grid;
  gap: 18px;
  padding: 32px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 28px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.contact-form label {
  display: grid;
  gap: 10px;
  font-weight: 600;
}

.form-actions {
  align-items: center;
}

.form-status {
  font-size: 0.95rem;
}

.contact-card {
  max-width: 420px;
}

.site-footer {
  width: min(1120px, calc(100% - 40px));
  margin: 60px auto 40px;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  border-top: 1px solid var(--border);
  padding-top: 28px;
}

.footer-links {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
}

.footer-links a {
  color: var(--text-muted);
}

.watchlist-card {
  display: grid;
  gap: 16px;
}

.watchlist-card h3 {
  margin-bottom: 8px;
}

.watchlist-card .watchlist-card__meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.watchlist-card button {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text);
  width: 100%;
}

.market-panel {
  border-radius: 28px;
  padding: 24px;
}

.market-sections {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 30px;
}

.stock-hero,
.contact-hero,
.portfolio-hero,
.page-intro {
  align-items: start;
}

.stock-summary-card,
.contact-card {
  max-width: 400px;
}

.page-intro .search-bar,
.watchlist-controls {
  width: 100%;
}

@media (max-width: 1024px) {
  .hero-section,
  .stock-hero,
  .portfolio-hero,
  .contact-hero,
  .page-intro {
    grid-template-columns: 1fr;
  }

  .feature-grid,
  .testimonial-grid,
  .index-grid,
  .trending-grid,
  .portfolio-cards,
  .stock-detail-cards,
  .watchlist-grid,
  .market-sections {
    grid-template-columns: 1fr;
  }

  .nav-menu {
    gap: 18px;
  }
}

@media (max-width: 768px) {
  .navbar {
    flex-wrap: wrap;
    justify-content: space-between;
  }

  .nav-toggle,
  .theme-toggle {
    display: inline-flex;
  }

  .nav-menu {
    width: 100%;
    display: none;
    flex-direction: column;
    background: var(--surface);
    padding: 20px;
    border: 1px solid var(--border);
    border-radius: 24px;
  }

  .nav-menu.open {
    display: flex;
  }

  .nav-menu a {
    padding: 12px 0;
    border-bottom: 1px solid var(--border);
  }

  .nav-menu a:last-child {
    border-bottom: none;
  }

  .hero-section,
  .stock-hero,
  .portfolio-hero,
  .contact-hero,
  .page-intro {
    padding: 20px 0;
  }

  .site-footer {
    flex-direction: column;
    align-items: flex-start;
  }
}

.dark {
  background: #0f172a;
  color: #e2e8f0;
}

.dark a {
  color: #e2e8f0;
}

.dark .surface,
.dark .market-card,
.dark .feature-card,
.dark .testimonial-card,
.dark .index-card,
.dark .market-panel,
.dark .stock-summary-card,
.dark .detail-card,
.dark .mini-card,
.dark .holdings-table,
.dark .contact-card,
.dark .watchlist-card,
.dark .contact-form {
  background: #111827;
  border-color: #334155;
}

.dark .navbar,
.dark .nav-menu {
  background: transparent;
}

.dark .nav-menu a {
  color: #cbd5e1;
}

.dark .footer-links a {
  color: #cbd5e1;
}

.dark .btn-secondary {
  background: rgba(255, 255, 255, 0.08);
}

.dark .contact-form input,
.dark .contact-form textarea,
.dark .search-bar input,
.dark .watchlist-controls input {
  background: #111827;
  border-color: #334155;
  color: #e2e8f0;
}

.dark .form-status {
  color: #a5b4fc;
}

