  --primary-hover: #1d4ed8;
  --success: #16a34a;
  --danger: #dc2626;
  --border: #e5e7eb;
  --shadow: 0 24px 80px rgba(15, 23, 42, 0.08);
}

/* Load Inter font as primary */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background 0.35s ease, color 0.35s ease;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea {
  font-family: inherit;
}

.navbar {
  width: min(1120px, calc(100% - 40px));
  margin: 12px auto;
  padding: 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(15,23,42,0.04);
}

.brand a {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.brand a:hover{color:var(--primary)}

.nav-menu {
  display: flex;
  gap: 20px;
  align-items: center;
}

.nav-menu a {
  color: var(--text-muted);
  position: relative;
  transition: color 0.18s ease, transform 0.12s ease;
  padding: 8px 10px;
  border-radius: 8px;
}

.nav-menu a:hover,
.nav-menu a.active {
  color: var(--text);
  transform: translateY(-2px);
  background: rgba(37,99,235,0.06);
}

.nav-menu a.active::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 3px;
  background: var(--primary);
  border-radius: 999px;
}

.nav-toggle,
.theme-toggle {
  display: none;
  border: none;
  background: transparent;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--text);
}

.main,
footer,
section {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
}

.hero-section,
.stock-hero,
.portfolio-hero,
.contact-hero,
.page-intro {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 36px;
  align-items: center;
  padding: 40px 0 20px;
}

.hero-copy h1,
.page-intro h1,
.stock-hero h1,
.contact-hero h1 {
  font-size: clamp(2rem, 3.2vw, 3.2rem);
  line-height: 1.05;
  margin-bottom: 16px;
}

.eyebrow {
  display: inline-block;
  margin-bottom: 16px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.78rem;
}

.hero-copy p,
.stock-description,
.page-intro p,
.contact-hero p {
  max-width: 720px;
