  line-height: 1.75;
}

.hero-actions,
.cta-group,
.watchlist-controls,
.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 24px;
}

.btn {
  border: none;
  border-radius: 999px;
  padding: 14px 24px;
  cursor: pointer;
  font-weight: 600;
  transition: transform 0.2s ease, background 0.2s ease;
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-secondary {
  background: rgba(37, 99, 235, 0.08);
  color: var(--text);
}

.btn:hover {
  transform: translateY(-1px);
}

