    gap: 8px;
    width: 100%;
    margin-top: 8px;
    padding: 0 12px;
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    transition: max-height 260ms ease, opacity 240ms ease;
  }

  .nav-menu.open {
    max-height: 420px;
    opacity: 1;
  }

  .nav-menu a { padding: 10px 8px; }

  .theme-toggle { order: 3; }

  .hero-copy h1 { font-size: 1.6rem; }
  .section-heading h2 { font-size: 1.2rem; }
  .testimonial-grid, .feature-grid { grid-template-columns: 1fr; }
}

/* Small-screen usability */
@media (max-width: 768px) {
  .cta-group { flex-direction: column; gap: 12px; }
  .cta-group .btn { width: 100%; }

  .watchlist-grid, .index-grid, .trending-grid {
    grid-template-columns: 1fr !important;
  }

  .watchlist-card {
    padding: 16px;
  }

  .watchlist-card button {
    width: 100%;
    margin-top: 8px;
  }

  .contact-form {
    padding: 18px;
  }

  .contact-form input,
  .contact-form textarea {
    padding: 12px;
    font-size: 0.95rem;
  }

  .table-row { grid-template-columns: 1fr 1fr; gap: 8px; }
  .table-row .table-header { display: none; }

  .stock-summary-card { margin-top: 18px; }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .hero-copy h1 { font-size: 2.2rem; }
  .brand a { font-size: 1.4rem; }
  .index-grid, .trending-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid { grid-template-columns: repeat(2, minmax(180px,1fr)); }
}

@media (min-width: 1025px) and (max-width: 1440px) {
  .hero-copy h1 { font-size: clamp(2.2rem, 3vw, 2.8rem); }
  .index-grid { grid-template-columns: repeat(3, 1fr); }
  .trending-grid { grid-template-columns: repeat(3, 1fr); }
  .navbar { width: min(1000px, calc(100% - 40px)); }
}

@media (min-width: 1441px) {
  .navbar { width: 1120px; }
}

:root {
  --bg: #f5f7fb;
  --surface: #ffffff;
  --surface-strong: #ffffff;
  --text: #1f2937;
  --text-muted: #6b7280;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --success: #16a34a;
  --danger: #dc2626;
  --border: #e5e7eb;
  --shadow: 0 24px 80px rgba(15, 23, 42, 0.08);
}

body.dark {
  --bg: #0f172a;
  --surface: #111827;
  --surface-strong: #0f172a;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --primary: #5b8cff;
  --primary-hover: #3b82f6;
  --success: #22c55e;
  --danger: #f97316;
  --border: #334155;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.28);
}

/* Load Inter font as primary */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Inter, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background 0.35s ease, color 0.35s ease;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea {
  font-family: inherit;
}

.navbar {
  width: min(1120px, calc(100% - 40px));
  margin: 12px auto;
  padding: 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(15,23,42,0.04);
}

.brand a {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.brand a:hover{color:var(--primary)}

.nav-menu {
  display: flex;
  gap: 20px;
  align-items: center;
}

.nav-menu a {
  color: var(--text-muted);
  position: relative;
  transition: color 0.18s ease, transform 0.12s ease;
  padding: 8px 10px;
  border-radius: 8px;
}

.nav-menu a:hover,
.nav-menu a.active {
  color: var(--text);
  transform: translateY(-2px);
  background: rgba(37,99,235,0.06);
}

.nav-menu a.active::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 100%;
  height: 3px;
  background: var(--primary);
  border-radius: 999px;
}

.nav-toggle,
.theme-toggle {
  border: none;
  background: transparent;
  font-size: 1.3rem;
  cursor: pointer;
  color: var(--text);
}

.theme-toggle {
  display: inline-flex;
}

.nav-toggle {
  display: none;
}

body.menu-open {
  overflow: hidden;
}

.navbar { position: relative; z-index: 1100; }

.main,
footer,
section {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
}

.hero-section,
.stock-hero,
.portfolio-hero,
.contact-hero,
.page-intro {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 36px;
  align-items: center;
  padding: 40px 0 20px;
}

.hero-copy h1,
.page-intro h1,
.stock-hero h1,
.contact-hero h1 {
  font-size: clamp(2rem, 3.2vw, 3.2rem);
  line-height: 1.05;
  margin-bottom: 16px;
}

.eyebrow {
  display: inline-block;
  margin-bottom: 16px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.78rem;
}

.hero-copy p,
.stock-description,
.page-intro p,
.contact-hero p {
  max-width: 720px;
  color: var(--text-muted);
  line-height: 1.75;
}

.hero-actions,
.cta-group,
.watchlist-controls,
.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 24px;
}

.btn {
  border: none;
  border-radius: 999px;
  padding: 14px 24px;
  cursor: pointer;
  font-weight: 600;
  transition: transform 0.2s ease, background 0.2s ease;
}

/* Make buttons more tappable on smaller screens */
@media (max-width: 768px) {
  .btn { padding: 14px 18px; font-size: 1rem; }
  .btn-primary, .btn-secondary { width: auto; }
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-secondary {
